// oleg.ae/ig-viral-ecom: generated by projects/mike_side_hustle/ig_viral_ecom/build_page.py in the vault. Edit there.
export const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Duskway Funnel</title>\n<style>\n:root { --bg:#0b0f17; --panel:#131a26; --line:#243042; --fg:#e9edf3; --mute:#93a0b4; --amber:#f5b324; --ink:#1a1200; --dim:#2a3648; --green:#4fd08a }\n* { box-sizing:border-box }\nbody { margin:0; background:var(--bg); color:var(--fg); font:15px/1.45 -apple-system,\"Inter\",system-ui,sans-serif; padding:28px 24px 48px }\nmain { max-width:1180px; margin:0 auto }\nh1 { font-size:26px; margin:0 0 4px; letter-spacing:-.01em }\n.sub { color:var(--mute); margin:0 0 22px; font-size:13px }\n.sub a { color:var(--amber) }\n.cols { display:grid; grid-template-columns:minmax(0,1.1fr) minmax(0,1fr); gap:28px; align-items:start }\n.card { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:20px }\nsvg { display:block; width:100%; height:auto }\nsvg text { font-family:inherit; fill:var(--fg) }\n.ctl { padding:14px 0; border-bottom:1px solid var(--line) }\n.ctl:first-child { padding-top:0 } .ctl:last-child { border-bottom:0; padding-bottom:0 }\n.ctl .top { display:flex; justify-content:space-between; align-items:baseline; gap:12px; margin-bottom:8px }\n.ctl label { font-weight:600 }\n.ctl output { font:700 22px/1 ui-monospace,\"SF Mono\",Menlo,monospace; color:var(--amber); font-variant-numeric:tabular-nums }\n.wrap { position:relative; height:22px }\n.wrap::before { content:\"\"; position:absolute; left:0; right:0; top:8px; height:6px; background:var(--dim); border-radius:3px }\n.band { position:absolute; top:8px; height:6px; background:var(--amber); opacity:.55; border-radius:3px; pointer-events:none }\ninput[type=range] { position:absolute; inset:0; width:100%; margin:0; background:transparent; -webkit-appearance:none; appearance:none }\ninput[type=range]::-webkit-slider-runnable-track { height:6px; background:transparent; border-radius:3px }\ninput[type=range]::-webkit-slider-thumb { -webkit-appearance:none; width:20px; height:20px; border-radius:50%; background:var(--amber); border:3px solid var(--bg); margin-top:-7px; cursor:grab }\ninput[type=range]:focus-visible { outline:2px solid var(--amber); outline-offset:4px; border-radius:4px }\n.ends { display:flex; justify-content:space-between; font-size:11px; color:var(--mute); margin-top:4px; font-variant-numeric:tabular-nums }\n.hint { font-size:12px; color:var(--mute); margin-top:4px }\n.presets { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:16px }\nbutton { font:600 13px/1 inherit; color:var(--fg); background:transparent; border:1px solid var(--line); border-radius:999px; padding:9px 14px; cursor:pointer }\nbutton:hover { border-color:var(--amber) } button.on { background:var(--amber); color:var(--ink); border-color:var(--amber) }\n.money { display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-top:28px }\n.money div { background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:18px 20px }\n.money span { display:block; color:var(--mute); font-size:12px; letter-spacing:.12em; text-transform:uppercase; margin-bottom:6px }\n.money strong { font:700 clamp(34px,5vw,56px)/1 ui-monospace,\"SF Mono\",Menlo,monospace; font-variant-numeric:tabular-nums }\n.money .p strong { color:var(--green) }\n.money small { display:block; color:var(--mute); margin-top:8px; font-size:13px }\n@media (max-width:860px) { .cols { grid-template-columns:1fr } }\n</style>\n</head>\n<body>\n<main>\n<h1>Duskway funnel</h1>\n<p class=\"sub\"><a href=\"https://www.instagram.com/duskway.store/\">instagram.com/duskway.store</a>: 142.9M plays on 16 reels in 5 days, 17 to 22 Nov 2026. Move any slider. The pale amber band on each track is the range the research supports.</p>\n\n<div class=\"cols\">\n  <div class=\"card\"><svg id=\"fun\" viewBox=\"0 0 600 470\" role=\"img\" aria-label=\"Funnel from plays to orders\"></svg>\n    <p class=\"hint\">Bar widths are on a log scale, so the small steps stay visible.</p></div>\n\n  <div class=\"card\">\n    <div class=\"presets\">\n      <button data-p=\"oleg\">1% and 1%</button>\n      <button data-p=\"research\">Research middle</button>\n    </div>\n    <div class=\"ctl\"><div class=\"top\"><label for=\"plays\">Plays</label><output id=\"o_plays\"></output></div>\n      <div class=\"wrap\"><input type=\"range\" id=\"plays\" min=\"0\" max=\"1\" step=\"any\"></div><div class=\"ends\"><span>50M</span><span>500M</span></div></div>\n    <div class=\"ctl\"><div class=\"top\"><label for=\"v2s\">Plays that open the website</label><output id=\"o_v2s\"></output></div>\n      <div class=\"wrap\"><span class=\"band\" id=\"b_v2s\"></span><input type=\"range\" id=\"v2s\" min=\"0\" max=\"1\" step=\"any\"></div><div class=\"ends\"><span>0.01%</span><span>3%</span></div></div>\n    <div class=\"ctl\"><div class=\"top\"><label for=\"s2b\">Website visitors who buy</label><output id=\"o_s2b\"></output></div>\n      <div class=\"wrap\"><span class=\"band\" id=\"b_s2b\"></span><input type=\"range\" id=\"s2b\" min=\"0\" max=\"1\" step=\"any\"></div><div class=\"ends\"><span>0.1%</span><span>10%</span></div></div>\n    <div class=\"ctl\"><div class=\"top\"><label for=\"ltv\">LTV per customer</label><output id=\"o_ltv\"></output></div>\n      <div class=\"wrap\"><span class=\"band\" id=\"b_ltv\"></span><input type=\"range\" id=\"ltv\" min=\"0\" max=\"1\" step=\"any\"></div><div class=\"ends\"><span>$15</span><span>$100</span></div></div>\n    <div class=\"ctl\"><div class=\"top\"><label for=\"mar\">Profit margin</label><output id=\"o_mar\"></output></div>\n      <div class=\"wrap\"><span class=\"band\" id=\"b_mar\"></span><input type=\"range\" id=\"mar\" min=\"0\" max=\"1\" step=\"any\"></div><div class=\"ends\"><span>10%</span><span>90%</span></div></div>\n  </div>\n</div>\n\n<div class=\"money\">\n  <div><span>Revenue</span><strong id=\"rev\"></strong><small id=\"rev_s\"></small></div>\n  <div class=\"p\"><span>Profit</span><strong id=\"pro\"></strong><small id=\"pro_s\"></small></div>\n</div>\n</main>\n\n<script>\n// each control: range, log or linear scale, researched 5th to 95th percentile band, formatter\nconst C = {\n  plays:{min:50e6,max:500e6,log:true, fmt:v=>(v/1e6).toFixed(1)+'M'},\n  v2s:{min:.0001,max:.03,log:true,band:[.00023,.00147],fmt:v=>(v*100).toFixed(v<.001?3:2)+'%'},\n  s2b:{min:.001,max:.10,log:true,band:[.004,.025],fmt:v=>(v*100).toFixed(2)+'%'},\n  ltv:{min:15,max:100,log:false,band:[28,40],fmt:v=>'$'+v.toFixed(0)},\n  mar:{min:.10,max:.90,log:false,band:[.54,.74],fmt:v=>(v*100).toFixed(0)+'%'}\n};\nconst P = {\n  research:{plays:142.9e6,v2s:.00052,s2b:.010,ltv:34,mar:.65},\n  oleg:{plays:142.9e6,v2s:.01,s2b:.01,ltv:34,mar:.70}\n};\nconst $ = id => document.getElementById(id);\nconst toV = (c,t) => c.log ? c.min*Math.pow(c.max/c.min,t) : c.min+(c.max-c.min)*t;\nconst toT = (c,v) => c.log ? Math.log(v/c.min)/Math.log(c.max/c.min) : (v-c.min)/(c.max-c.min);\nconst num = v => v>=1e6 ? (v/1e6).toFixed(v>=1e7?1:2)+'M' : v>=1e5 ? Math.round(v/1e3)+'k' : v>=1e3 ? (v/1e3).toFixed(1)+'k' : Math.round(v).toString();\nconst usd = v => '$'+(v>=1e6 ? (v/1e6).toFixed(2)+'M' : v>=1e3 ? Math.round(v/1e3)+'k' : Math.round(v));\nconst val = {};\n\nfunction draw() {\n  for (const k in C) { val[k] = toV(C[k], +$(k).value); $('o_'+k).textContent = C[k].fmt(val[k]); }\n  const visits = val.plays*val.v2s, orders = visits*val.s2b, rev = orders*val.ltv, pro = rev*val.mar;\n  $('rev').textContent = usd(rev); $('pro').textContent = usd(pro);\n  $('rev_s').textContent = num(orders)+' orders x '+C.ltv.fmt(val.ltv);\n  $('pro_s').textContent = C.mar.fmt(val.mar)+' of revenue, '+usd(pro/Math.max(orders,1))+' per order';\n\n  // funnel: three stages, width by log10\n  const W=600, cx=300, maxW=560, minW=120, top=Math.log10(500e6);\n  const w = n => Math.max(minW, maxW*Math.log10(Math.max(n,1))/top);\n  const st = [['Plays',val.plays,'#f5b324'],['Website visits',visits,'#d99a1b'],['Orders',orders,'#b47d12']];\n  const h=92, gap=74; let y=10, s='';\n  st.forEach((a,i)=>{\n    const w1=w(a[1]), w2 = i<2 ? (w1+w(st[i+1][1]))/2 : w1*0.86;\n    s += `<polygon points=\"${cx-w1/2},${y} ${cx+w1/2},${y} ${cx+w2/2},${y+h} ${cx-w2/2},${y+h}\" fill=\"${a[2]}\"/>`;\n    s += `<text x=\"${cx}\" y=\"${y+38}\" text-anchor=\"middle\" style=\"fill:#1a1200;font-size:13px;font-weight:600;letter-spacing:.08em\">${a[0].toUpperCase()}</text>`;\n    s += `<text x=\"${cx}\" y=\"${y+72}\" text-anchor=\"middle\" style=\"fill:#1a1200;font-size:32px;font-weight:700;font-family:ui-monospace,Menlo,monospace\">${num(a[1])}</text>`;\n    if (i<2) {\n      const k = i ? 's2b' : 'v2s', one = Math.round(1/val[k]);\n      s += `<line x1=\"${cx}\" y1=\"${y+h+8}\" x2=\"${cx}\" y2=\"${y+h+gap-8}\" stroke=\"#243042\" stroke-width=\"2\"/>`;\n      s += `<rect x=\"${cx-150}\" y=\"${y+h+16}\" width=\"300\" height=\"42\" rx=\"21\" fill=\"#0b0f17\" stroke=\"#243042\"/>`;\n      s += `<text x=\"${cx}\" y=\"${y+h+43}\" text-anchor=\"middle\" style=\"font-size:15px;font-weight:600\"><tspan style=\"fill:#f5b324\">${C[k].fmt(val[k])}</tspan><tspan style=\"fill:#93a0b4\">  \u00b7  1 in ${one.toLocaleString()}</tspan></text>`;\n    }\n    y += h+gap;\n  });\n  $('fun').innerHTML = s;\n\n  document.querySelectorAll('button[data-p]').forEach(b => {\n    const p = P[b.dataset.p];\n    b.classList.toggle('on', Object.keys(p).every(k => Math.abs(toT(C[k],p[k]) - $(k).value) < .0006));\n  });\n}\nfunction set(p) { for (const k in p) $(k).value = toT(C[k],p[k]); draw(); }\nfor (const k in C) {\n  $(k).addEventListener('input', draw);\n  if (C[k].band) { const a=toT(C[k],C[k].band[0]), b=toT(C[k],C[k].band[1]); const e=$('b_'+k); e.style.left=(a*100)+'%'; e.style.width=((b-a)*100)+'%'; }\n}\ndocument.querySelectorAll('button[data-p]').forEach(b => b.addEventListener('click', () => set(P[b.dataset.p])));\nset(P.oleg);\n</script>\n</body>\n</html>\n";
